#define main instance_oracle_main
#include "instance-oracle.cpp"
#undef main
#include <iomanip>
#include <cstring>
uint64_t hbyte(uint64_t h,unsigned char b){return (h^b)*1099511628211ULL;}
template<class T>uint64_t hvalue(uint64_t h,const T& value){const auto* p=reinterpret_cast<const unsigned char*>(&value);for(size_t i=0;i<sizeof(T);++i)h=hbyte(h,p[i]);return h;}
void quote(std::ostream& out,const std::string& value){out<<'"';for(unsigned char c:value){if(c=='"'||c=='\\')out<<'\\'<<char(c);else if(c<32){out<<"\\u00"<<"0123456789abcdef"[c>>4]<<"0123456789abcdef"[c&15];}else out<<char(c);}out<<'"';}
void coord(std::ostream& out,const Coord& c){out<<'['<<c.x()<<','<<c.y()<<','<<c.z()<<']';}
void vector(std::ostream& out,const Vec3d& v){out<<'['<<v.x()<<','<<v.y()<<','<<v.z()<<']';}
template<class Grid>void scalarSummary(std::ostream& out,const Grid& grid){using T=typename Grid::ValueType;uint64_t h=14695981039346656037ULL;uint64_t values=0;for(auto it=grid.tree().cbeginValueAll();it;++it){Coord c=it.getCoord();h=hvalue(h,c.x());h=hvalue(h,c.y());h=hvalue(h,c.z());h=hvalue(h,int(it.getDepth()));h=hvalue(h,uint8_t(it.isValueOn()?1:0));T value=*it;h=hvalue(h,value);++values;}out<<",\"background\":"<<double(grid.background())<<",\"values\":"<<values<<",\"hash\":\""<<h<<"\",\"samples\":[";int i=0;for(Coord c:{Coord(-4096),Coord(-129,0,0),Coord(-128,0,0),Coord(-9,0,0),Coord(-8,0,0),Coord(-1,0,0),Coord(0),Coord(1,2,3),Coord(7,0,0),Coord(8,0,0),Coord(9,0,0),Coord(127,0,0),Coord(128,0,0),Coord(129,0,0),Coord(4096,0,0),Coord(4100,2,3)}){if(i++)out<<',';out<<'[';coord(out,c);out<<','<<double(grid.tree().getValue(c))<<','<<(grid.tree().isValueOn(c)?"true":"false")<<','<<grid.tree().getValueDepth(c)<<']';}out<<']';}
void summary(std::ostream& out,const GridBase::Ptr& grid){out<<"{\"name\":";quote(out,grid->getName());out<<",\"type\":";quote(out,grid->type());out<<",\"map\":";quote(out,grid->transform().mapType());out<<",\"active\":"<<grid->activeVoxelCount()<<",\"leaves\":"<<grid->baseTree().leafCount()<<",\"empty\":"<<(grid->empty()?"true":"false")<<",\"bbox\":[";CoordBBox b=grid->evalActiveVoxelBoundingBox();coord(out,b.min());out<<',';coord(out,b.max());out<<"],\"metadata\":[";bool first=true;for(auto it=grid->beginMeta();it!=grid->endMeta();++it){if(!first)out<<',';first=false;out<<'[';quote(out,it->first);out<<',';quote(out,it->second->typeName());out<<',';quote(out,it->second->str());out<<']';}out<<']';if(grid->isType<FloatGrid>())scalarSummary(out,*gridPtrCast<FloatGrid>(grid));else if(grid->isType<DoubleGrid>())scalarSummary(out,*gridPtrCast<DoubleGrid>(grid));else if(grid->isType<Int32Grid>())scalarSummary(out,*gridPtrCast<Int32Grid>(grid));else if(grid->isType<Int64Grid>())scalarSummary(out,*gridPtrCast<Int64Grid>(grid));else if(grid->isType<BoolGrid>())scalarSummary(out,*gridPtrCast<BoolGrid>(grid));else if(grid->isType<MaskGrid>())scalarSummary(out,*gridPtrCast<MaskGrid>(grid));out<<'}';}
template<class Grid>typename Grid::Ptr data(const std::string& name,int kind){using T=typename Grid::ValueType;auto grid=Grid::create(T(-7));grid->setName(name);grid->insertMeta("source",Int32Metadata(kind));grid->tree().addTile(3,Coord(-4096),T(2),true);grid->tree().addTile(3,Coord(4096,0,0),T(3),false);grid->tree().addTile(2,Coord(128,0,0),T(4),true);grid->tree().addTile(1,Coord(8,0,0),T(5),false);grid->tree().setValueOn(Coord(1,2,3),T(17));grid->tree().setValueOff(Coord(-1,0,0),T(23));for(int x=-9;x<=9;++x)grid->tree().setValueOn(Coord(x,0,0),T(x+32));if(kind==0){auto transform=math::Transform::createLinearTransform(.375);transform->postTranslate(Vec3d(1.25,-2.5,.75));grid->setTransform(transform);}else if(kind==1){auto transform=math::Transform::createLinearTransform(.7);transform->postRotate(.31,math::Z_AXIS);transform->postTranslate(Vec3d(-.25,.75,1.125));grid->setTransform(transform);}else if(kind==2){grid->setTransform(math::Transform::Ptr(new math::Transform(math::MapBase::Ptr(new math::NonlinearFrustumMap(BBoxd(Vec3d(-8,-6,-4),Vec3d(8,6,12)),.65,9.0)))));}return grid;}
std::vector<BBoxd> boxes(){return {BBoxd(),BBoxd(Vec3d(10),Vec3d(-10)),BBoxd(Vec3d(-10000),Vec3d(10000)),BBoxd(Vec3d(-2),Vec3d(2)),BBoxd(Vec3d(0),Vec3d(0)),BBoxd(Vec3d(-.5,.5,-1.5),Vec3d(-.5,.5,-1.5)),BBoxd(Vec3d(1.2,-2.6,.7),Vec3d(1.7,-2.1,1.2)),BBoxd(Vec3d(3.7,-2.6,.7),Vec3d(4.4,-2.1,1.2)),BBoxd(Vec3d(49,-3,-1),Vec3d(51,0,2)),BBoxd(Vec3d(1537,-3,-1),Vec3d(1539,0,2)),BBoxd(Vec3d(1e6),Vec3d(1e6+1))};}
void observations(std::ostream& out,const fs::path& path,bool& first,int& count){io::File file(path.string());file.open(false);std::vector<std::string> names;for(auto it=file.beginName();it!=file.endName();++it)names.push_back(*it);auto emit=[&](const char* operation,const std::string& name,int box,const GridBase::Ptr& grid){if(!first)out<<",\n";first=false;++count;out<<"{\"file\":";quote(out,path.filename().string());out<<",\"operation\":";quote(out,operation);out<<",\"name\":";quote(out,name);out<<",\"box\":"<<box<<",\"grid\":";summary(out,grid);out<<'}';};for(const auto& name:names){emit("metadata",name,-1,file.readGridMetadata(name));emit("grid",name,-1,file.readGrid(name));for(size_t i=0;i<boxes().size();++i)emit("box",name,int(i),file.readGrid(name,boxes()[i]));}auto metadata=file.readAllGridMetadata();for(size_t i=0;i<metadata->size();++i)emit("all-metadata",std::to_string(i),-1,(*metadata)[i]);auto grids=file.getGrids();for(size_t i=0;i<grids->size();++i)emit("all",std::to_string(i),-1,(*grids)[i]);if(!first)out<<",\n";first=false;out<<"{\"file\":";quote(out,path.filename().string());out<<",\"operation\":\"names\",\"names\":[";for(size_t i=0;i<names.size();++i){if(i)out<<',';quote(out,names[i]);}out<<"]}";++count;file.close();}
void generatePartial(const fs::path& dir){fs::create_directories(dir);GridPtrVec grids;auto a=data<FloatGrid>("zeta",0);auto inst=gridPtrCast<FloatGrid>(a->copyGrid());inst->setName("instance");inst->setTransform(math::Transform::createLinearTransform(2));grids={a,data<DoubleGrid>("repeat",1),data<Int32Grid>("repeat",2),inst,data<Int64Grid>("",3)};auto b=BoolGrid::create(false);b->setName("boolean");b->tree().setValueOn(Coord(1,2,3),true);b->tree().setValueOff(Coord(-1,0,0),true);grids.push_back(b);auto mask=MaskGrid::create();mask->setName("mask");mask->tree().addTile(1,Coord(8,0,0),true,true);mask->tree().setValueOn(Coord(1,2,3));grids.push_back(mask);std::vector<fs::path> files;MetaMap metadata;metadata.insertMeta("file",StringMetadata("native partial file"));for(int compression:{0,4,6}){auto path=dir/("native-partial-"+std::to_string(compression)+".vdb");io::File file(path.string());file.setCompression(compression);file.setGridStatsMetadataEnabled(false);file.write(grids,metadata);files.push_back(path);}auto streaming=dir/"native-partial-stream.vdb";{std::ofstream stream(streaming,std::ios::binary);io::Stream archive(stream);archive.setCompression(6);archive.setGridStatsMetadataEnabled(false);archive.write(grids,metadata);}files.push_back(streaming);for(bool seek:{false,true}){auto path=dir/(std::string("native-partial-chain-")+(seek?"seek":"stream")+".vdb");GridPtrVec chain={a->copyGrid(),a->copyGrid(),a->copyGrid()};std::vector<std::string> names={"z_middle","a_child","m_base"},parents={"m_base","z_middle",""};initializeGrids(chain,names);ExplicitArchive().emit(path,chain,names,parents,seek);files.push_back(path);}std::ofstream out(dir/"native-partial.json.tmp");out<<std::setprecision(17)<<"{\"boxes\":[";bool first=true;for(auto box:boxes()){if(!first)out<<',';first=false;out<<'[';vector(out,box.min());out<<',';vector(out,box.max());out<<']';}out<<"],\"cases\":[\n";first=true;int count=0;for(const auto& path:files)observations(out,path,first,count);out<<"\n]}\n";out.close();fs::path target=dir/"native-partial.json";if(fs::exists(target))fs::remove(target);fs::rename(dir/"native-partial.json.tmp",target);std::cout<<"Generated "<<count<<" native File observations in "<<files.size()<<" archives\n";}
void generateSkippedBuffer(const fs::path& dir){
 fs::create_directories(dir);auto grid=data<FloatGrid>("skip",0);auto path=dir/"native-partial-skipped-buffer.vdb";
 {io::File output(path.string());output.setCompression(io::COMPRESS_BLOSC);output.setGridStatsMetadataEnabled(false);output.write(GridPtrVec{grid});}
 std::ifstream in(path,std::ios::binary);io::StreamMetadata::Ptr metadata(new io::StreamMetadata);io::setStreamMetadataPtr(in,metadata,false);io::setCurrentVersion(in);
 in.seekg(57);MetaMap fileMetadata;fileMetadata.readMeta(in);int32_t count;in.read(reinterpret_cast<char*>(&count),4);if(count!=1)throw std::runtime_error("skip descriptor count");io::GridDescriptor descriptor;descriptor.read(in);descriptor.seekToBlocks(in);
 util::NodeMask<3> mask;mask.load(in);char code;in.read(&code,1);if(code!=6)throw std::runtime_error("skip mask code");int64_t length;in.read(reinterpret_cast<char*>(&length),8);if(length<=0)throw std::runtime_error("expected Blosc-compressed first leaf");auto payload=static_cast<int64_t>(in.tellg());in.close();
 {std::fstream edit(path,std::ios::binary|std::ios::in|std::ios::out);edit.seekp(payload);char invalid=0;edit.write(&invalid,1);}
 auto world=grid->indexToWorld(Vec3d(1,2,3));BBoxd box(world,world);io::File file(path.string());file.open(false);auto partial=file.readGrid("skip",box);bool rejected=false;try{file.readGrid("skip");}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("native full read accepted invalid Blosc");
 std::ofstream out(dir/"native-partial-skipped-buffer.json");out<<std::setprecision(17)<<"{\"payload\":"<<payload<<",\"length\":"<<length<<",\"world\":";vector(out,world);out<<",\"fullReadRejected\":true,\"grid\":";summary(out,partial);out<<"}\n";std::cout<<"Native regional read skipped an invalid Blosc payload; full read rejected it\n";
}int main(int argc,char** argv){try{initialize();if(argc==3&&std::string(argv[1])=="generate"){generatePartial(argv[2]);generateSkippedBuffer(argv[2]);}else if(argc==3&&std::string(argv[1])=="skip")generateSkippedBuffer(argv[2]);else throw std::runtime_error("usage: file-partial-reference generate directory");return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}